//! Independent reference values for the Johnson SU/SB/SL fits.
//!
//! `tests/reference/johnson.json` is generated by `tools/gen_johnson.py` with
//! scipy; the test never runs Python.

use fp_core::data::{MissingPolicy, Sample};
use fp_core::dists::Distribution;
use fp_core::johnson::{Johnson, JohnsonFamily};
use serde_json::Value;

fn reference() -> Value {
    let raw = include_str!("reference/johnson.json");
    serde_json::from_str(raw).expect("valid JSON reference")
}

fn sample(values: &Value) -> Sample {
    Sample::new(
        values
            .as_array()
            .expect("values")
            .iter()
            .map(|value| value.as_f64().expect("value"))
            .collect(),
        MissingPolicy::Drop,
    )
    .expect("sample")
}

#[test]
fn the_su_fit_reaches_the_scipy_likelihood() {
    let r = reference();
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let data = sample(&r["su"]);
    let fitted = Johnson::fit(&data, JohnsonFamily::Su).expect("SU fit");
    let likelihood = fitted.log_likelihood(&data).expect("likelihood");
    let scipy = r["su_scipy_log_likelihood"].as_f64().expect("scipy");
    assert!(
        likelihood >= scipy - tolerance,
        "SU: {likelihood} vs scipy {scipy}"
    );
    assert!(fitted.cdf(0.0) > 0.0 && fitted.cdf(0.0) < 1.0);
    assert!(fitted.quantile(0.5).is_finite());
}

#[test]
fn the_sl_fit_reaches_the_scipy_likelihood() {
    let r = reference();
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let data = sample(&r["sl"]);
    let fitted = Johnson::fit(&data, JohnsonFamily::Sl).expect("SL fit");
    let likelihood = fitted.log_likelihood(&data).expect("likelihood");
    let scipy = r["sl_scipy_log_likelihood"].as_f64().expect("scipy");
    assert!(
        likelihood >= scipy - tolerance,
        "SL: {likelihood} vs scipy {scipy}"
    );
}

#[test]
fn the_sb_fit_improves_on_the_true_parameters() {
    let r = reference();
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let data = sample(&r["sb"]);
    let fitted = Johnson::fit(&data, JohnsonFamily::Sb).expect("SB fit");
    let likelihood = fitted.log_likelihood(&data).expect("likelihood");
    let truth = r["sb_true_log_likelihood"].as_f64().expect("true");
    assert!(
        likelihood >= truth - tolerance,
        "SB: {likelihood} vs truth {truth}"
    );
}

#[test]
fn the_best_family_has_the_smallest_aic() {
    let r = reference();
    let data = sample(&r["su"]);
    let best = Johnson::fit_best(&data).expect("best fit");
    let best_aic = best.aic(&data).expect("aic");
    for family in [JohnsonFamily::Su, JohnsonFamily::Sb, JohnsonFamily::Sl] {
        if let Ok(fitted) = Johnson::fit(&data, family) {
            assert!(
                best_aic <= fitted.aic(&data).expect("aic") + 1e-9,
                "{} beat the selected family",
                family.name()
            );
        }
    }
}
